using UnityEditor; using UnityEditor.SceneManagement; using UnityEngine; public static class Phase4A_HierarchyProbe { [MenuItem("147VR/Phase4/Probe") ] public static void Run(){ var s=EditorSceneManager.OpenScene("Assets/Scenes/147VR_MainScene.unity",OpenSceneMode.Single); var t=GameObject.Find("Prefab_WPBSA_12Foot_Snooker"); foreach(var x in t.GetComponentsInChildren<Transform>(true)){ if(x.name.Contains("TABLE SURFACE")||x.name.Contains("VISUAL_MAIN")||x.name.Contains("Visual_Meshes")) Debug.Log($"[PROBE] {Path(x)} local={x.localScale} world={x.lossyScale} rot={x.eulerAngles} pos={x.position}"); } } static string Path(Transform t){string p=t.name; while(t.parent!=null){t=t.parent;p=t.name+"/"+p;} return p;} }